use automerge::{AutoCommit,ActorId,ReadDoc,ObjType,ObjId,ROOT,transaction::Transactable};
use serde_json::{Value,json};use std::collections::{BTreeMap,BTreeSet};
struct Peer{doc:AutoCommit,known:BTreeSet<usize>,counter:u64}
fn random(seed:&mut u32,n:usize)->usize{*seed^=*seed<<13;*seed^=*seed>>17;*seed^=*seed<<5;*seed as usize%n}
fn cursor(d:&AutoCommit,o:&ObjId,p:usize)->String{d.get_cursor(o,p,None).unwrap().to_string()}
fn snapshot(p:&Peer,o:&ObjId)->Value{json!({"known":p.known.iter().collect::<Vec<_>>(),"text":p.doc.text(o).unwrap()})}
fn main(){let mut seed=64997;for trial in 0..160{let n=3+random(&mut seed,3);let mut base=AutoCommit::new();base.set_actor(ActorId::from(vec![0]));let object=base.put_object(ROOT,"text",ObjType::Text).unwrap();base.commit();let mut peers:Vec<Peer>=(0..n).map(|i|{let mut doc=base.fork();doc.set_actor(ActorId::from(vec![i as u8+1]));Peer{doc,known:BTreeSet::new(),counter:0}}).collect();let mut ids=BTreeMap::new();let mut operations=vec![];let mut states=vec![];for _ in 0..70{let pi=random(&mut seed,n);if random(&mut seed,4)==0{let qi=random(&mut seed,n);let mut other=peers[qi].doc.fork();let known=peers[qi].known.clone();peers[pi].doc.merge(&mut other).unwrap();peers[pi].known.extend(known);}else{let p=&mut peers[pi];let text=p.doc.text(&object).unwrap();let len=text.chars().count();let insert=len==0||random(&mut seed,4)!=0;let pos=random(&mut seed,len+usize::from(insert));let empty=json!({"id":0,"left":0,"right":0,"stamp":0,"value":0,"deleted":true});let op;if insert{let left=if pos==0{0}else{ids[&cursor(&p.doc,&object,pos-1)]};let value=[97+random(&mut seed,26)as u32,233,30000][random(&mut seed,3)];p.doc.splice_text(&object,pos,0,&char::from_u32(value).unwrap().to_string()).unwrap();p.doc.commit();let raw=cursor(&p.doc,&object,pos);let stamp=raw.split('@').next().unwrap().parse::<u64>().unwrap();p.counter+=1;let id=((pi as u64+1)<<32)|p.counter;ids.insert(raw,id);op=json!({"insert":true,"atom":{"id":id,"left":left,"right":0,"stamp":stamp,"value":value,"deleted":false},"target":0});}else{let target=ids[&cursor(&p.doc,&object,pos)];p.doc.splice_text(&object,pos,1,"").unwrap();p.doc.commit();op=json!({"insert":false,"atom":empty,"target":target});}p.known.insert(operations.len());operations.push(op);}states.push(snapshot(&peers[pi],&object));}for pi in 0..n{for qi in 0..n{let mut other=peers[qi].doc.fork();let known=peers[qi].known.clone();peers[pi].doc.merge(&mut other).unwrap();peers[pi].known.extend(known);}states.push(snapshot(&peers[pi],&object));}println!("{}",json!({"trial":trial,"operations":operations,"states":states}));}}
